mapper.delete:
DELETE FROM quest_reward
WHERE campaign_code = #{campaignCode} AND quest_code = #{questCode}
  AND policy_version = #{policyVersion}

mapper.select:
SELECT COUNT(*)
FROM quest_campaign
WHERE id <> #{campaignId}
  AND status = 'ACTIVE'
  AND start_at < #{endAt}
  AND end_at > #{startAt}
